import { GOAL_STEP_INDEX, STEPS, type GoalId, type WizardStepId } from "./content";

/**
 * Pure flow rules for the first-run tour. No React, no storage, no DOM — the
 * whole sequence can be reasoned about and tested as plain functions.
 */

export const ONBOARDING_VERSION = 1;
export const LAST_STEP_INDEX = STEPS.length - 1;

export type OnboardingStatus = "pending" | "active" | "done" | "skipped";

export interface OnboardingState {
  status: OnboardingStatus;
  step: number;
  goal: GoalId | null;
  version: number;
}

export function createOnboardingState(
  overrides: Partial<OnboardingState> = {},
): OnboardingState {
  return {
    status: "pending",
    step: 0,
    goal: null,
    version: ONBOARDING_VERSION,
    ...overrides,
  };
}

export function clampStep(step: number): number {
  if (!Number.isFinite(step)) {
    return 0;
  }
  return Math.min(LAST_STEP_INDEX, Math.max(0, Math.trunc(step)));
}

export function stepAt(step: number): WizardStepId {
  return STEPS[clampStep(step)].id;
}

/** A tour the user has neither finished nor skipped should greet them. */
export function shouldAutoOpen(state: OnboardingState): boolean {
  return state.status === "pending" || state.status === "active";
}

export function isFinished(state: OnboardingState): boolean {
  return state.status === "done" || state.status === "skipped";
}

/** Replay: start from the top, forget the previous choice. */
export function startTour(state: OnboardingState): OnboardingState {
  return { ...state, status: "active", step: 0, goal: null };
}

export function advanceTour(state: OnboardingState): OnboardingState {
  if (isFinished(state)) {
    return state;
  }
  // The flow will not leave the starting-point step without a choice.
  if (state.step === GOAL_STEP_INDEX && state.goal === null) {
    return state;
  }
  return { ...state, status: "active", step: clampStep(state.step + 1) };
}

export function retreatTour(state: OnboardingState): OnboardingState {
  if (isFinished(state)) {
    return state;
  }
  return { ...state, status: "active", step: clampStep(state.step - 1) };
}

export function selectGoal(state: OnboardingState, goal: GoalId): OnboardingState {
  return { ...state, goal };
}

export function finishTour(state: OnboardingState): OnboardingState {
  return { ...state, status: "done", step: LAST_STEP_INDEX };
}

export function skipTour(state: OnboardingState): OnboardingState {
  return { ...state, status: "skipped" };
}
import { useCallback, useEffect, useMemo, useState, type ReactNode } from "react";

import { isFeatureEnabled } from "../features/flags";
import { OnboardingContext, type OnboardingController } from "./context";
import type { GoalId } from "./content";
import {
  advanceTour,
  createOnboardingState,
  finishTour,
  retreatTour,
  selectGoal,
  shouldAutoOpen,
  skipTour,
  startTour,
  type OnboardingState,
} from "./machine";
import { readOnboardingState, writeOnboardingState } from "./storage";

export interface OnboardingProviderProps {
  children: ReactNode;
  /** Override for tests and stories; defaults to the `firstRunWizard` flag. */
  enabled?: boolean;
}

export function OnboardingProvider({ children, enabled }: OnboardingProviderProps) {
  const featureEnabled = enabled ?? isFeatureEnabled("firstRunWizard");

  const [state, setState] = useState<OnboardingState>(
    () => readOnboardingState() ?? createOnboardingState(),
  );
  const [open, setOpen] = useState<boolean>(() => featureEnabled && shouldAutoOpen(state));

  // Persist every transition so closing the app mid-tour resumes where it left off.
  useEffect(() => {
    if (featureEnabled) {
      writeOnboardingState(state);
    }
  }, [featureEnabled, state]);

  const chooseGoal = useCallback((goal: GoalId) => {
    setState((prev) => selectGoal(prev, goal));
  }, []);

  const advance = useCallback(() => {
    setState(advanceTour);
  }, []);

  const back = useCallback(() => {
    setState(retreatTour);
  }, []);

  const complete = useCallback(() => {
    setState(finishTour);
    setOpen(false);
  }, []);

  const skip = useCallback(() => {
    setState(skipTour);
    setOpen(false);
  }, []);

  const restart = useCallback(() => {
    if (!featureEnabled) {
      return;
    }
    setState(startTour);
    setOpen(true);
  }, [featureEnabled]);

  const value = useMemo<OnboardingController>(
    () => ({
      enabled: featureEnabled,
      open,
      state,
      chooseGoal,
      advance,
      back,
      complete,
      skip,
      restart,
    }),
    [featureEnabled, open, state, chooseGoal, advance, back, complete, skip, restart],
  );

  return <OnboardingContext.Provider value={value}>{children}</OnboardingContext.Provider>;
}
